INSERT INTO "News" ("id","title","body","author","pinned","createdAt","updatedAt") VALUES ('cmuxklp4h00c7ql34s3p5wlyy','Registry milestone: 400+ incidents archived','The archive crossed 400 mirror-verified incidents this month. Thanks to every researcher who filed a responsible disclosure.','GadaLuBau',true,'2026-10-07T03:51:08.658Z','2026-10-07T03:51:08.658Z');
INSERT INTO "News" ("id","title","body","author","pinned","createdAt","updatedAt") VALUES ('cmuxklp4h00c8ql3495f77w4b','New special-archive filter live','Special archives now group incidents by domain pattern (*.gov.*, *.go.*, *.ac.*, *.edu.*). Browse them under Archive Special.','GadaLuBau',false,'2026-10-07T03:51:08.658Z','2026-10-07T03:51:08.658Z');
INSERT INTO "News" ("id","title","body","author","pinned","createdAt","updatedAt") VALUES ('cmuxklp4h00c9ql34hgas009x','On-hold verification window updated','Fresh submissions are held for a 10-minute verification window before promotion to the verified archive. Admins can still promote manually.','GadaLuBau',false,'2026-10-07T03:51:08.658Z','2026-10-07T03:51:08.658Z');
INSERT INTO "News" ("id","title","body","author","pinned","createdAt","updatedAt") VALUES ('cmuxklp4h00caql34w6bzvxy3','Team leaderboard + year filter','Ranking now supports a Defacers / Teams toggle and per-year filtering. Switch modes from the Ranking page.','GadaLuBau',false,'2026-10-07T03:51:08.658Z','2026-10-07T03:51:08.658Z');
INSERT INTO "News" ("id","title","body","author","pinned","createdAt","updatedAt") VALUES ('cmuxklp4h00cbql3481qfwsv5','Reminder: ethics first','We log, mirror, and attribute — we do not exfiltrate, doxx, or sell. Submissions violating the charter are refused.','GadaLuBau',false,'2026-10-07T03:51:08.658Z','2026-10-07T03:51:08.658Z');